class Solution {
    public int[] countBits(int n) {
        int[] ans = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            ans[i] = ans[i >> 1] + (i & 1);
        }
        return ans;
    }
}

class Solution {
    public int[] countBits(int n) {
        int[] ans = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            ans[i] = ans[i & (i - 1)] + 1;
        }
        return ans;
    }
}

class Solution {
    public int[] countBits(int n) {
        int[] ans = new int[n + 1];
        int highestPowerOfTwo = 0;
        for (int i = 1; i <= n; i++) {
            if ((i & (i - 1)) == 0) {
                highestPowerOfTwo = i;
            }
            ans[i] = ans[i - highestPowerOfTwo] + 1;
        }
        return ans;
    }
}

class Solution {
    public int[] countBits(int n) {
        int[] ans = new int[n + 1];
        int offset = 1;
        while (offset <= n) {
            for (int i = 0; i < offset && i + offset <= n; i++) {
                ans[i + offset] = ans[i] + 1;
            }
            offset <<= 1;
        }
        return ans;
    }
}

class Solution {
    public int[] countBits(int n) {
        int[] ans = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int x = i;
            int count = 0;
            while (x != 0) {
                x &= (x - 1);
                count++;
            }
            ans[i] = count;
        }
        return ans;
    }
}
